const context = $('Restaurar contexto ENSAYO').first().json;
const m=context.message; const audio=Boolean(m.voice || m.audio);
const transcript=audio?String($json.text||'').trim():null;
if(audio&&!transcript)throw new Error('Transcripción vacía');
return [{json:{...context,channel:'telegram',environment:'ensayo',event_id:'telegram:'+context.update_id,
 session_id:'orok:ensayo:telegram:comercial03:'+context.chat_id,
 text:audio?transcript:(m.text||(m.contact?'Contacto compartido: '+JSON.stringify(m.contact):'Formato no soportado; solicita texto o audio.')),
 message_type:audio?'audio':m.contact?'contact':'text',transcription:transcript,
 received_at:new Date(m.date*1000).toISOString(),contact:m.contact||null,
 previous_profile:context.state?.profile||{},derivation_status:context.state?.derivation?.status||'none'}}];

const source = $('Normalizar Telegram ENSAYO').first().json;
const agente = $('Lola Telegram ENSAYO').first().json;
const entrada = $input.first().json;

if (entrada.output === undefined || entrada.output === null) {
  throw new Error('La entrada no contiene la ficha formateada');
}

let d;

if (typeof entrada.output === 'object') {
  d = entrada.output;
} else {
  const raw = String(entrada.output)
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/([}\]])\s*[`"']+\s*$/, '$1')
    .trim();

  try {
    d = JSON.parse(raw);
  } catch {
    throw new Error('La ficha formateada no es JSON válido');
  }
}

if (
  !d ||
  typeof d.reply !== 'string' ||
  !d.reply.trim() ||
  !d.profile ||
  typeof d.profile !== 'object' ||
  Array.isArray(d.profile)
) {
  throw new Error('Ficha de ensayo inválida');
}

const anterior = source.previous_profile || {};
const p = { ...anterior };

for (const k of [
  'name',
  'phone',
  'email',
  'interest',
  'purchase_method',
  'initial_payment'
]) {
  if (typeof d.profile[k] === 'string' && d.profile[k].trim()) {
    p[k] = d.profile[k].trim().slice(0, 300);
  }
}

let invalid = null;

if (p.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.email)) {
  p.email = anterior.email || null;
  invalid = 'correo';
}

if (p.phone) {
  const digits = p.phone.replace(/\D/g, '');

  if (digits.length < 7 || digits.length > 15) {
    p.phone = anterior.phone || null;
    invalid = 'teléfono';
  }
}

const missing = ['name', 'phone', 'email'].filter(k => !p[k]);
const text = String(source.text || '');

const explicit =
  /\b(asesor|vendedor|persona real|cotizaci[oó]n|visita|negociar)\b/i
    .test(text);

const optOut =
  d.opt_out === true ||
  /no quiero recibir|no me (?:escribas|contactes)|deja de (?:escribir|enviar)/i
    .test(text);

const status = source.derivation_status;

const offer =
  !optOut &&
  !['pending', 'prepared', 'accepted'].includes(status) &&
  (
    explicit ||
    (
      !['declined', 'expired'].includes(status) &&
      (d.handoff === true || missing.length === 0)
    )
  );

const steps = Array.isArray(agente.intermediateSteps)
  ? agente.intermediateSteps
  : [];

const actualTools = [
  ...new Set(
    steps
      .map(s => s.action?.tool || s.tool)
      .filter(Boolean)
  )
];

const commercialVerified =
  d.commercial_answer === true && actualTools.length > 0;

let reply = d.reply.slice(0, 500);

if (invalid) {
  reply = 'Gracias. ¿Podrías confirmar tu ' +
    invalid + '? Parece incompleto.';
}

if (d.commercial_answer === true && !commercialVerified) {
  reply = 'Necesito verificar esa información en el catálogo antes ' +
    'de confirmártela. Puedo ofrecerte continuar con un asesor.';
}

if (optOut) {
  reply = 'Entendido. No recibirás más respuestas automáticas en ' +
    'este ensayo. Si deseas retomarlo, escribe /ensayo_retomar.';
}

return [{
  json: {
    ...source,
    kind: 'profile',
    event_id: 'profile:' + source.update_id,
    profile: p,
    missing_fields: missing,
    reply,
    handoff: d.handoff === true,
    opt_out: optOut,
    offer_agent: offer,
    request_id: source.chat_id + '_' + source.update_id,
    commercial_verified: commercialVerified,
    tools_used: actualTools,
    commercial_evidence:
      commercialVerified && Array.isArray(d.commercial_evidence)
        ? d.commercial_evidence
            .filter(e => e && actualTools.includes(e.tool))
            .slice(0, 10)
        : [],
    crm_status: 'NO_ESCRITO_ENSAYO'
  }
}];

const raw = $input.first().json;
const q=raw.callback_query; const m=q?.message || raw.message;
if(!m || m.chat?.type!=='private' || (q?.from || m.from)?.is_bot) return [];
const actor=q?.from || m.from; const id=String(m.chat.id);
if(String(actor.id)!==id) return [];
if(q){const match=/^orok:(yes|no):([0-9]+_[0-9]+)$/.exec(q.data||'');
 if(!match)throw new Error('Botón no reconocido de este ensayo');
 return [{json:{kind:'selection',event_id:'selection:'+q.id,chat_id:id,user_id:String(actor.id),
 request_id:match[2],choice:match[1],query_id:q.id,message_id:String(m.message_id)}}];}
return [{json:{kind:'ingress',event_id:'ingress:'+raw.update_id,chat_id:id,user_id:String(actor.id),
 update_id:raw.update_id,message:m,text:m.text||'',resume:/^\/ensayo_retomar(?:\s|$)/.test(m.text||'')}}];

const evento = $('Identificar evento ENSAYO').first().json;
const resultado = $input.first().json.data;

return [{
  json: {
    ...evento,
    ...resultado
  }
}];

const ficha = $('Validar ficha ENSAYO').first().json;
const resultado = $input.first().json.data;

if (!resultado || !resultado.state) {
  throw new Error('No se recibió el estado de Guardar ficha de prueba');
}

return [{
  json: {
    ...ficha,
    state: resultado.state,
    crm_status: 'NO_ESCRITO_ENSAYO'
  }
}];

