const source = $('Identificar evento ENSAYO').first().json;
const result = $('Resolver seleccion asesor').first().json.data;

if (!result || !result.state) {
  throw new Error('No se recibió el resultado de Resolver seleccion asesor');
}

let reply =
  'Esta opción ya fue atendida o corresponde a una oferta anterior. ' +
  'No cambiamos la decisión registrada.';

if (result.accepted === true) {
  if (source.choice === 'yes') {
    reply =
      'Aceptación anotada en el ensayo. Se creó una tarea de prueba ' +
      'y Lola queda pausada. Todavía no se notificó a un vendedor real.';
  } else if (source.choice === 'no') {
    reply =
      'Entendido. Tu contacto queda en Seguimiento en el registro ' +
      'de ensayo, con la nota de que ahora no deseas continuar con asesor.';
  }
}

return [{
  json: {
    ...source,
    ...result,
    reply,
    crm_status: 'NO_ESCRITO_ENSAYO'
  }
}];

