CREATE TABLE IF NOT EXISTS public.orok_lola_ensayo03_leads (
 chat_id text PRIMARY KEY, user_id text NOT NULL, state jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.orok_lola_ensayo03_events (
 event_id text PRIMARY KEY, chat_id text NOT NULL, kind text NOT NULL,
 payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION public.orok_lola_ensayo03_apply(p jsonb) RETURNS jsonb
LANGUAGE plpgsql AS $fn$
DECLARE
 s jsonb; d jsonb; vchat text:=p->>'chat_id'; vuser text:=p->>'user_id';
 k text:=p->>'kind'; eid text:=p->>'event_id'; inserted integer;
 request_id text:=p->>'request_id'; status text; note text; ts timestamptz:=clock_timestamp();
 eligible boolean:=false; should_send boolean:=false; accepted boolean:=false;
BEGIN
 IF vchat IS NULL OR vchat !~ '^[0-9]+$' THEN RAISE EXCEPTION 'Chat de ensayo inválido'; END IF;
 IF k='ingress' THEN
  INSERT INTO public.orok_lola_ensayo03_leads(chat_id,user_id,state)
  VALUES(vchat,vuser,jsonb_build_object('profile','{}'::jsonb,'stage','Lead Inicial',
   'bot_paused',false,'opt_out',false,'derivation','{}'::jsonb,'notes','[]'::jsonb,'tasks','[]'::jsonb))
  ON CONFLICT(chat_id) DO NOTHING;
 END IF;
 SELECT state INTO s FROM public.orok_lola_ensayo03_leads WHERE chat_id=vchat FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('chat_id',vchat,'accepted',false,'reason','Sin contacto de ensayo'); END IF;
 IF k IN ('ingress','profile','offer','offer_sent','selection') THEN
  IF NOT EXISTS(SELECT 1 FROM public.orok_lola_ensayo03_leads WHERE chat_id=vchat AND user_id=vuser)
   THEN RETURN jsonb_build_object('chat_id',vchat,'accepted',false,'reason','Identidad distinta'); END IF;
  IF eid IS NULL THEN RAISE EXCEPTION 'Falta identificador único de evento'; END IF;
  INSERT INTO public.orok_lola_ensayo03_events(event_id,chat_id,kind,payload)
   VALUES(eid,vchat,k,p) ON CONFLICT(event_id) DO NOTHING;
  GET DIAGNOSTICS inserted=ROW_COUNT;
  IF inserted=0 THEN RETURN jsonb_build_object('chat_id',vchat,'state',s,'duplicate',true,
   'eligible',false,'should_send',false,'accepted',false); END IF;
 END IF;
 d:=COALESCE(s->'derivation','{}'::jsonb); status:=d->>'status';
 IF k='ingress' THEN
  IF COALESCE((p->>'resume')::boolean,false) THEN
   s:=s||jsonb_build_object('bot_paused',false,'opt_out',false,'stage','Lead Inicial',
    'derivation',jsonb_build_object('status','reset'));
   s:=jsonb_set(s,'{notes}',COALESCE(s->'notes','[]'::jsonb)||jsonb_build_array(jsonb_build_object(
    'at',ts,'text','Reanudación explícita de la conversación de ENSAYO')));
  END IF;
  eligible:=NOT COALESCE((s->>'bot_paused')::boolean,false) AND NOT COALESCE((s->>'opt_out')::boolean,false);
 ELSIF k='profile' THEN
  s:=jsonb_set(s,'{profile}',COALESCE(s->'profile','{}'::jsonb)||jsonb_strip_nulls(COALESCE(p->'profile','{}'::jsonb)));
  s:=s||jsonb_build_object('last_message',p->>'text','commercial_evidence',COALESCE(p->'commercial_evidence','[]'::jsonb));
  IF COALESCE((p->>'opt_out')::boolean,false) THEN
   s:=s||jsonb_build_object('opt_out',true,'bot_paused',true,'stage','Seguimiento');
   IF status IN ('prepared','pending') THEN s:=jsonb_set(s,'{derivation,status}','"cancelled"'::jsonb); END IF;
   s:=jsonb_set(s,'{notes}',COALESCE(s->'notes','[]'::jsonb)||jsonb_build_array(jsonb_build_object(
    'at',ts,'text','Solicitó no recibir más mensajes; bot pausado y derivación pendiente cancelada')));
  END IF;
 ELSIF k='offer' THEN
  IF NOT COALESCE((s->>'opt_out')::boolean,false) AND NOT COALESCE((s->>'bot_paused')::boolean,false)
   AND COALESCE(status,'') NOT IN ('pending','prepared','accepted') THEN
   d:=jsonb_build_object('request_id',request_id,'status','prepared','prepared_at',ts);
   s:=jsonb_set(s,'{derivation}',d); should_send:=true;
  END IF;
 ELSIF k='offer_sent' THEN
  IF d->>'request_id'=request_id AND status='prepared' THEN
   d:=d||jsonb_build_object('status','pending','offered_at',ts,'expires_at',ts+interval '24 hours',
    'message_id',p->>'message_id');
   s:=jsonb_set(s,'{derivation}',d);
   s:=jsonb_set(s,'{notes}',COALESCE(s->'notes','[]'::jsonb)||jsonb_build_array(jsonb_build_object(
    'at',ts,'text','Se ofreció continuar con asesor mediante botones; plazo de 24 horas')));
  END IF;
 ELSIF k='selection' THEN
  IF d->>'request_id'=request_id AND status IN ('prepared','pending','expired') AND p->>'choice' IN ('yes','no')
   AND NOT COALESCE((s->>'opt_out')::boolean,false) THEN
   accepted:=true;
   IF p->>'choice'='yes' THEN
    note:='Aceptó continuar con un asesor. Tarea de ENSAYO creada; sin vendedor real notificado';
    IF status='expired' OR (d->>'expires_at' IS NOT NULL AND (d->>'expires_at')::timestamptz<ts)
     THEN note:=note||'. Aceptación posterior al plazo de 24 horas'; END IF;
    d:=d||jsonb_build_object('status','accepted','responded_at',ts);
    s:=s||jsonb_build_object('stage','Atención asesor pendiente','bot_paused',true);
    s:=jsonb_set(s,'{tasks}',COALESCE(s->'tasks','[]'::jsonb)||jsonb_build_array(jsonb_build_object(
     'request_id',request_id,'role','vendedor','status','simulado_pendiente','created_at',ts)));
   ELSE
    note:='Declinó continuar con un asesor en este momento';
    d:=d||jsonb_build_object('status','declined','responded_at',ts);
    s:=s||jsonb_build_object('stage','Seguimiento','bot_paused',false);
   END IF;
   s:=jsonb_set(s,'{derivation}',d);
   s:=jsonb_set(s,'{notes}',COALESCE(s->'notes','[]'::jsonb)||jsonb_build_array(jsonb_build_object('at',ts,'text',note)));
  END IF;
 ELSIF k IN ('expire','simulate_expiry') THEN
  IF status='pending' AND (k='simulate_expiry' OR (d->>'expires_at')::timestamptz<=ts) THEN
   d:=d||jsonb_build_object('status','expired','expired_at',ts,'simulated',k='simulate_expiry');
   s:=s||jsonb_build_object('stage','Seguimiento','derivation',d);
   note:='No respondió a la opción de continuar con un asesor en 24 horas';
   IF k='simulate_expiry' THEN note:='SIMULACIÓN DE ENSAYO: '||note; END IF;
   s:=jsonb_set(s,'{notes}',COALESCE(s->'notes','[]'::jsonb)||jsonb_build_array(jsonb_build_object('at',ts,'text',note)));
  END IF;
 ELSIF k<>'read' THEN RAISE EXCEPTION 'Operación de ensayo desconocida'; END IF;
 IF k<>'read' THEN UPDATE public.orok_lola_ensayo03_leads SET state=s,updated_at=ts WHERE chat_id=vchat; END IF;
 RETURN jsonb_build_object('chat_id',vchat,'state',s,'eligible',eligible,'should_send',should_send,'accepted',accepted,
  'crm_status','NO_ESCRITO_ENSAYO');
END; $fn$;
SELECT true AS initialized;

