DO $check$
BEGIN
  IF to_regprocedure('public.orok_lola_ensayo03_apply(jsonb)') IS NULL
     OR to_regclass('public.orok_lola_ensayo03_leads') IS NULL
     OR to_regclass('public.orok_lola_ensayo03_events') IS NULL THEN
    RAISE EXCEPTION 'Falta la base ENSAYO 03: comprobar credencial y entorno existentes antes de instalar botones 04';
  END IF;
END;
$check$;
-- SOLO ENSAYO. Complementa la función 03 existente; no borra ni reinicializa fichas.
-- Ejecutar una vez con la MISMA credencial Postgres del ensayo.
CREATE OR REPLACE FUNCTION public.orok_lola_ensayo04_selection(p jsonb)
RETURNS jsonb LANGUAGE plpgsql AS $fn$
DECLARE
  c text := p->>'choice'; r jsonb; s jsonb; mapped jsonb;
  note text; oldnote text; stage text; task jsonb;
BEGIN
  IF p->>'kind' IS DISTINCT FROM 'selection' OR c IS NULL
     OR c NOT IN ('appointment','seller','showroom','yes','no') THEN
    RAISE EXCEPTION 'Selección no reconocida';
  END IF;
  IF p->>'request_id' IS NULL OR p->>'chat_id' IS NULL
     OR split_part(p->>'request_id','_',1) IS DISTINCT FROM p->>'chat_id' THEN
    RAISE EXCEPTION 'Solicitud de otro chat';
  END IF;
  -- La función 03 conserva bloqueo, identidad, deduplicación, baja y vigencia de solicitud.
  mapped := p || jsonb_build_object('choice',CASE WHEN c='no' THEN 'no' ELSE 'yes' END,
                                    'requested_action',c);
  r := public.orok_lola_ensayo03_apply(mapped);
  IF NOT COALESCE((r->>'accepted')::boolean,false) THEN RETURN r; END IF;
  IF c IN ('yes','no') THEN RETURN r; END IF;
  s := r->'state';
  oldnote := s#>>'{notes,-1,text}';
  IF c='seller' THEN
    stage := 'Atención asesor pendiente';
    note := 'Eligió Hablar con un vendedor. Derivación y tarea SIMULADAS; ningún vendedor real notificado';
  ELSIF c='appointment' THEN
    stage := 'Cita pendiente de coordinar';
    note := 'Eligió Agendar cita. Solicitud de ENSAYO registrada; sin evento en Calendar ni invitación enviada';
  ELSE
    stage := 'Visita showroom pendiente de coordinar';
    note := 'Eligió Visitar el showroom. Solicitud de ENSAYO registrada; sin visita reservada ni evento en Calendar';
  END IF;
  IF oldnote LIKE '%posterior al plazo%' THEN
    note := note || '. Selección posterior al plazo de 24 horas';
  END IF;
  s := s || jsonb_build_object('stage',stage,'bot_paused',c='seller');
  s := jsonb_set(s,'{derivation}',(s->'derivation') || jsonb_build_object('choice',c));
  s := jsonb_set(s,'{notes,-1,text}',to_jsonb(note));
  task := (s#>'{tasks,-1}') || jsonb_build_object('action',c,'status',
     CASE WHEN c='seller' THEN 'simulado_pendiente' ELSE 'simulado_agendamiento_pendiente' END);
  s := jsonb_set(s,'{tasks,-1}',task);
  UPDATE public.orok_lola_ensayo03_leads SET state=s,updated_at=clock_timestamp()
    WHERE chat_id=p->>'chat_id';
  RETURN r || jsonb_build_object('state',s,'crm_status','NO_ESCRITO_ENSAYO');
END;
$fn$;
SELECT true AS initialized_selection04;

