const context = $('Restaurar contexto ENSAYO1').first().json;
const m=context.message; const audio=Boolean(m.voice || m.audio);
const transcript=audio?String($json.text||'').trim():null;
if(audio&&!transcript)throw new Error('Transcripción vacía');
return [{json:{...context,channel:'telegram',environment:'ensayo',event_id:'telegram:'+context.update_id,
 session_id:'orok:ensayo:telegram:comercial03:'+context.chat_id,
 text:audio?transcript:(m.text||(m.contact?'Contacto compartido: '+JSON.stringify(m.contact):'Formato no soportado; solicita texto o audio.')),
 message_type:audio?'audio':m.contact?'contact':'text',transcription:transcript,
 received_at:new Date(m.date*1000).toISOString(),contact:m.contact||null,
 previous_profile:context.state?.profile||{},derivation_status:context.state?.derivation?.status||'none'}}];

const source = $('Normalizar Telegram ENSAYO1').first().json;
const agent = $('Lola Telegram ENSAYO1').first().json;
const input = $input.first().json;
let d = input.output;
if (d === undefined || d === null) throw new Error('Falta output de Lola');
if (typeof d === 'string') {
  const raw = d.trim().replace(/^```(?:json)?\s*/i,'').replace(/([}\]])\s*[`"']+\s*$/,'$1').trim();
  try { d = JSON.parse(raw); } catch { throw new Error('Lola no devolvió JSON válido'); }
}
if (d && typeof d.output === 'object' && d.reply === undefined) d=d.output;
if (!d || typeof d.reply !== 'string' || !d.reply.trim() || !d.profile ||
    typeof d.profile !== 'object' || Array.isArray(d.profile)) throw new Error('Ficha inválida');
const previous = source.previous_profile || {};
const profile = {...previous};
for (const k of ['name','phone','email','interest','purchase_method','initial_payment']) {
  if (typeof d.profile[k] === 'string' && d.profile[k].trim()) profile[k]=d.profile[k].trim().slice(0,300);
}
let invalid=null;
if (profile.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(profile.email)) {
  profile.email=previous.email||null; invalid='correo';
}
if (profile.phone) {
  const digits=String(profile.phone).replace(/\D/g,'');
  if (digits.length<7 || digits.length>15) {profile.phone=previous.phone||null;invalid='teléfono';}
}
const missing=['name','phone','email'].filter(k=>!profile[k]);
const text=String(source.text||'');
const economic=/precio|costo|descuento|promoci[oó]n|oferta|cotizaci[oó]n|cuota|inicial|financiamiento|forma de pago/i.test(text);
const explicit=/\b(asesor|vendedor|persona real|cotizaci[oó]n|visita(?:r)?|showroom|cita|agendar|negociar)\b/i.test(text);
const optOut=d.opt_out===true || /no quiero recibir|no me (?:escribas|contactes)|deja de (?:escribir|enviar)/i.test(text);
const status=source.derivation_status;
const resume=source.resume===true || /^\/ensayo_retomar(?:\s|$)/.test(text);
const paused=source.state?.bot_paused===true;
const offer=!optOut && !resume && !paused && !['pending','prepared','accepted'].includes(status) &&
  (explicit || (!['declined','expired'].includes(status) && d.handoff===true));
const steps=Array.isArray(agent.intermediateSteps)?agent.intermediateSteps:[];
const actualTools=[...new Set(steps.map(s=>s.action?.tool||s.tool).filter(Boolean))];
const commercialVerified=d.commercial_answer===true && actualTools.length>0;
let reply=d.reply.trim();
if (reply.length>450) {
  const cut=reply.slice(0,450); const boundary=Math.max(cut.lastIndexOf('.'),cut.lastIndexOf('?'),cut.lastIndexOf('!'));
  reply=boundary>80?cut.slice(0,boundary+1):'Puedo ayudarte a conocer las opciones y coordinar atención con ventas. ¿Qué te gustaría saber primero?';
}
if (invalid) reply='Gracias por compartir tus datos. ¿Podrías confirmar tu '+invalid+'? Parece incompleto.';
if (d.commercial_answer===true && !commercialVerified) {
  reply='Prefiero verificar esa información antes de confirmártela. Puedo ayudarte a continuar con ventas.';
}
if (offer && !invalid && /\b(showroom|visita(?:r)?|venir)\b/i.test(text)) {
  reply='¡Con gusto! 🏡 Será un gusto recibirte en el showroom. Elige cómo te gustaría continuar.';
} else if (offer && !invalid && /\b(cita|agendar)\b/i.test(text)) {
  reply='¡Con gusto! 📅 Elige cómo prefieres continuar para coordinar tu cita.';
} else if (offer && !invalid) {
  reply='¡Con gusto! 😊 Elige cómo prefieres continuar con nuestro equipo de ventas.';
}
if (economic && !optOut && !invalid) reply='Esa información comercial la revisará contigo un asesor. Puedo brindarte más información general sobre el proyecto o ayudarte a continuar con una de estas opciones.';
if (optOut) reply='Entendido. No recibirás más respuestas automáticas en este ensayo. Si deseas retomarlo, escribe /ensayo_retomar.';
return [{json:{...source,kind:'profile',event_id:'profile:'+source.update_id,profile,missing_fields:missing,
  reply,handoff:d.handoff===true||explicit||economic,opt_out:optOut,offer_agent:offer,
  request_id:source.chat_id+'_'+source.update_id,commercial_verified:commercialVerified,tools_used:actualTools,
  commercial_evidence:commercialVerified&&Array.isArray(d.commercial_evidence)?
    d.commercial_evidence.filter(e=>e&&actualTools.includes(e.tool)).slice(0,10):[],crm_status:'NO_ESCRITO_ENSAYO'}}];

const raw = $input.first().json;
const q = raw.callback_query;
const m = q?.message || raw.message;

if (
  !m ||
  m.chat?.type !== 'private' ||
  (q?.from || m.from)?.is_bot
) {
  return [];
}

const actor = q?.from || m.from;
const chat = String(m.chat.id);

if (String(actor.id) !== chat) {
  return [];
}

// BOTONES
if (q) {
  const callbackData = String(q.data || '');
  const cancelMatch =
  /^orok:cancel:(yes|no):([A-Za-z0-9_-]{10,128})$/
    .exec(callbackData);

if (cancelMatch) {
  return [{
    json: {
      kind: 'appointment_cancel_confirmation',
      event_id: 'appointment_cancel_confirmation:' + q.id,
      chat_id: chat,
      user_id: String(actor.id),
      update_id: raw.update_id,
      request_id:
        chat + '_' + String(raw.update_id),
      choice: cancelMatch[1],
      calendar_event_id: cancelMatch[2],
      query_id: q.id,
      message_id: String(m.message_id)
    }
  }];
}

  // Botón para elegir un horario de reprogramación.
  const reslotMatch =
    /^orok:reslot:([0-9]{10})$/.exec(callbackData);

  if (reslotMatch) {
    return [{
      json: {
        kind: 'reschedule_slot_selection',
        event_id: 'reschedule_slot:' + q.id,
        chat_id: chat,
        user_id: String(actor.id),
        update_id: raw.update_id,
        request_id:
          chat + '_' + String(raw.update_id),
        choice: 'reschedule_slot',
        slot_token: reslotMatch[1],
        query_id: q.id,
        message_id: String(m.message_id)
      }
    }];
  }

  // Botón para elegir una cita nueva.
  const slotMatch =
    /^orok:slot:([0-9]{10})$/.exec(callbackData);

  if (slotMatch) {
    return [{
      json: {
        kind: 'slot_selection',
        event_id: 'slot:' + q.id,
        chat_id: chat,
        user_id: String(actor.id),
        update_id: raw.update_id,
        request_id:
          chat + '_' + String(raw.update_id),
        choice: 'slot',
        slot_token: slotMatch[1],
        query_id: q.id,
        message_id: String(m.message_id)
      }
    }];
  }

  // Botones generales.
  const selectionMatch =
    /^orok:(appointment|seller|showroom|yes|no):([0-9]+_[0-9]+)$/
      .exec(callbackData);

  if (
    !selectionMatch ||
    !selectionMatch[2].startsWith(chat + '_')
  ) {
    throw new Error('Botón ajeno o no reconocido');
  }

  return [{
    json: {
      kind: 'selection',
      event_id: 'selection:' + q.id,
      chat_id: chat,
      user_id: String(actor.id),
      update_id: raw.update_id,
      request_id: selectionMatch[2],
      choice: selectionMatch[1],
      query_id: q.id,
      message_id: String(m.message_id)
    }
  }];
}

// MENSAJES
const text = String(m.text || '').trim();

const normalizedText = text
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();

const mentionsAppointment =
  /\b(cita|visita|showroom)\b/.test(normalizedText);

const requestsCancellation =
  mentionsAppointment &&
  (
    /\b(cancelar|cancela|cancelacion|anular|anula|eliminar)\b/
      .test(normalizedText) ||
    /\b(no podre asistir|no puedo asistir|no puedo ir|ya no voy)\b/
      .test(normalizedText)
  );

const requestsReschedule =
  mentionsAppointment &&
  (
    /\b(reprogramar|reprograma|cambiar|cambia|mover|mueve)\b/
      .test(normalizedText) ||
    /\b(otra fecha|otro horario|otra hora|otro dia)\b/
      .test(normalizedText)
  );

if (requestsCancellation) {
  return [{
    json: {
      kind: 'appointment_cancel_request',
      event_id:
        'appointment_cancel_request:' + raw.update_id,
      chat_id: chat,
      user_id: String(actor.id),
      update_id: raw.update_id,
      message: m,
      text
    }
  }];
}

if (requestsReschedule) {
  return [{
    json: {
      kind: 'appointment_change_request',
      event_id:
        'appointment_change_request:' + raw.update_id,
      chat_id: chat,
      user_id: String(actor.id),
      update_id: raw.update_id,
      message: m,
      text
    }
  }];
}

// MENSAJE NORMAL
return [{
  json: {
    kind: 'ingress',
    event_id: 'ingress:' + raw.update_id,
    chat_id: chat,
    user_id: String(actor.id),
    update_id: raw.update_id,
    message: m,
    text,
    resume:
      /^\/ensayo_retomar(?:\s|$)/.test(text)
  }
}];

const evento = $('Identificar evento ENSAYO1').first().json;
const resultado = $input.first().json.data;

return [{
  json: {
    ...evento,
    ...resultado
  }
}];

const ficha = $('Validar ficha ENSAYO1').first().json;
const resultado = $input.first().json.data;

if (!resultado || !resultado.state) {
  throw new Error('No se recibió el estado de Guardar ficha de prueba');
}

return [{
  json: {
    ...ficha,
    state: resultado.state,
    crm_status: 'NO_ESCRITO_ENSAYO'
  }
}];

