const event = $('Identificar evento ENSAYO1').first().json;
const resolved = $('Resolver seleccion asesor1').first().json;

const resolvedData = resolved.data || resolved;
const state = resolvedData.state || resolved.state || {};

const chatId =
  event.chat_id ||
  resolvedData.chat_id ||
  null;

const requestId =
  event.request_id ||
  state.derivation?.request_id ||
  resolvedData.request_id ||
  null;

const profile =
  state.profile ||
  resolvedData.profile ||
  {};

const zone = 'America/Lima';
const now = $now.setZone(zone);
const minimumStart = now.plus({ hours: 2 });

const slots = [];

for (let dayOffset = 0; dayOffset <= 7; dayOffset++) {
  const day = now.startOf('day').plus({ days: dayOffset });

  // Los lunes requieren coordinación especial.
  if (day.weekday === 1) continue;

  // Martes a domingo: horas de inicio entre 10:00 y 18:00.
  for (let hour = 10; hour <= 18; hour++) {
    const start = day.set({
      hour,
      minute: 0,
      second: 0,
      millisecond: 0
    });

    if (start < minimumStart) continue;

    const end = start.plus({ minutes: 45 });

    // Incluye 15 minutos de margen después de la cita.
    const availabilityEnd = start.plus({ minutes: 60 });

    slots.push({
      json: {
        chat_id: chatId,
        request_id: requestId,
        profile,
        slot_start: start.toISO(),
        slot_end: end.toISO(),
        availability_end: availabilityEnd.toISO(),
        slot_label: start
          .setLocale('es')
          .toFormat("ccc dd/LL · HH:mm"),
        slot_token: String(start.toUnixInteger())
      }
    });
  }
}

return slots.slice(0, 24);

const checks = $input.all();
const candidates = $('Generar horarios cita 04').all();

const available = checks
  .map((check, index) => ({
    ...(candidates[index]?.json || {}),
    available: check.json.available === true
  }))
  .filter(slot => slot.available);

// Mostrar como máximo dos horarios por día y seis en total.
const selected = [];
const quantityByDay = {};

for (const slot of available) {
  const day = String(slot.slot_start || '').slice(0, 10);

  if (!day) continue;

  quantityByDay[day] = quantityByDay[day] || 0;

  if (quantityByDay[day] >= 2) continue;

  selected.push(slot);
  quantityByDay[day]++;

  if (selected.length === 6) break;
}

const base = candidates[0]?.json || {};

if (selected.length === 0) {
  return [{
    json: {
      chat_id: base.chat_id,
      request_id: base.request_id,
      profile: base.profile || {},
      text:
        'Por el momento no encuentro horarios automáticos disponibles 📅. ' +
        'Con gusto puedo pedirle al equipo de ventas que coordine una alternativa contigo.',
      reply_markup: {
        inline_keyboard: []
      },
      available_slots: []
    }
  }];
}

const keyboard = [];

for (let index = 0; index < selected.length; index += 2) {
  keyboard.push(
    selected.slice(index, index + 2).map(slot => ({
      text: slot.slot_label,
      callback_data: `orok:slot:${slot.slot_token}`
    }))
  );
}

return [{
  json: {
    chat_id: base.chat_id,
    request_id: base.request_id,
    profile: base.profile || {},
    text:
      '¡Claro! 😊 Estos son los próximos horarios disponibles para visitar nuestro showroom:\n\n' +
      'Selecciona el que te acomode mejor. La cita se confirmará después de tu elección.\n\n' +
      'Si necesitas un lunes o después de las 7:00 p. m., escríbeme “horario especial” y ventas lo coordinará contigo.',
    reply_markup: {
      inline_keyboard: keyboard
    },
    available_slots: selected
  }
}];

const selection =
  $('Identificar evento ENSAYO1').first().json;

const token = Number(selection.slot_token);

if (!Number.isInteger(token)) {
  throw new Error('El horario seleccionado no es válido');
}

const startMilliseconds = token * 1000;
const currentMilliseconds = Date.now();

const minimumAllowed =
  currentMilliseconds + (2 * 60 * 60 * 1000);

const maximumAllowed =
  currentMilliseconds + (8 * 24 * 60 * 60 * 1000);

const start = new Date(startMilliseconds);
const end = new Date(startMilliseconds + (45 * 60 * 1000));
const availabilityEnd =
  new Date(startMilliseconds + (60 * 60 * 1000));

const slotValid =
  startMilliseconds >= minimumAllowed &&
  startMilliseconds <= maximumAllowed;

const label = new Intl.DateTimeFormat('es-PE', {
  timeZone: 'America/Lima',
  weekday: 'long',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
}).format(start);

return [{
  json: {
    ...selection,
    slot_valid: slotValid,
    slot_start: start.toISOString(),
    slot_end: end.toISOString(),
    availability_end: availabilityEnd.toISOString(),
    slot_label: label
  }
}];

const readNode =
  $('Leer ficha para cita 04').first().json;

let data = readNode.data || {};

if (typeof data === 'string') {
  try {
    data = JSON.parse(data);
  } catch {
    throw new Error(
      'No se pudo interpretar la ficha recuperada'
    );
  }
}

const state =
  data.state ||
  readNode.state ||
  {};

const profile =
  state.profile ||
  data.profile ||
  {};

const slot =
  $('Preparar horario elegido 04').first().json;

const name = String(
  profile.name || 'Interesado'
).trim();

const email = String(
  profile.email || ''
).trim().toLowerCase();

const phone = String(
  profile.phone || ''
).trim();

const interest = String(
  profile.interest || 'Consulta inmobiliaria'
).trim();

const validEmail =
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

if (!validEmail) {
  throw new Error(
    'La ficha no contiene un correo válido para enviar la invitación'
  );
}

if (!slot.slot_start || !slot.slot_end) {
  throw new Error(
    'No se encontró el horario elegido'
  );
}

const summary =
  `Visita showroom Infinity 224 - ${name}`;

const description = [
  'Cita generada por Lola desde Telegram.',
  '',
  `Cliente: ${name}`,
  `Teléfono: ${phone}`,
  `Correo: ${email}`,
  `Interés: ${interest}`,
  'Asesor de ventas: Antonio Garces',
  '',
  'Entorno actual: ENSAYO'
].join('\n');

return [{
  json: {
    chat_id: slot.chat_id,
    request_id: slot.request_id,
    slot_token: slot.slot_token,
    slot_start: slot.slot_start,
    slot_end: slot.slot_end,
    slot_label: slot.slot_label,
    name,
    email,
    phone,
    interest,
    summary,
    description,
    location: 'Calle La Apacheta 224, San Miguel'
  }
}];

const event =
  $('Crear cita Calendar 04').first().json;

const appointment =
  $('Preparar evento Calendar 04').first().json;

if (!event.id || event.status !== 'confirmed') {
  throw new Error(
    'Google Calendar no confirmó la creación de la cita'
  );
}

const firstName =
  String(appointment.name || 'cliente')
    .trim()
    .split(/\s+/)[0];

const text = [
  `¡Listo, ${firstName}! 😊`,
  '',
  `Tu visita al showroom de Infinity 224 quedó confirmada para el ${appointment.slot_label}`,
  '',
  `📍 ${appointment.location}`,
  `📧 Enviamos la invitación a ${appointment.email} desde ventas@orok.com.pe.`,
  '',
  'Si necesitas reprogramarla, escríbeme y con gusto te ayudaré.'
].join('\n');

return [{
  json: {
    chat_id: appointment.chat_id,
    text,
    event_id: event.id,
    event_url: event.htmlLink,
    slot_start: appointment.slot_start,
    slot_end: appointment.slot_end,
    slot_label: appointment.slot_label,
    name: appointment.name,
    email: appointment.email,
    phone: appointment.phone,
    interest: appointment.interest
  }
}];

