CREATE OR REPLACE FUNCTION public.orok_lola_ensayo04_book_appointment(p jsonb)
RETURNS jsonb
LANGUAGE plpgsql
AS $function$
DECLARE
  s jsonb;
  vchat text := p->>'chat_id';
