const row = $input.first().json;
const data = row.data || {};
const state = data.state || {};
const derivation = state.derivation || {};
const profile = state.profile || {};

const tasks = Array.isArray(state.tasks)
  ? state.tasks
  : [];

const appointmentTask = [...tasks]
  .reverse()
  .find(task =>
    task &&
    task.calendar_event_id &&
    !['cancelada', 'cancelled', 'reprogramada']
      .includes(String(task.status || '').toLowerCase())
  );

const calendarEventId =
  derivation.calendar_event_id ||
  appointmentTask?.calendar_event_id ||
  null;

const appointmentStart =
  derivation.appointment_start ||
  appointmentTask?.starts_at ||
  null;

const appointmentEnd =
  derivation.appointment_end ||
  null;

const source =
  $('Identificar evento ENSAYO1').first().json;
const derivationStatus =
  String(derivation.status || '').toLowerCase();

const hasActiveAppointment =
  Boolean(calendarEventId) &&
  ![
    'appointment_cancelled',
    'cancelled',
    'cancelada'
  ].includes(derivationStatus);
return [{
  json: {
    kind: source.kind,
    event_id: source.event_id,
    chat_id: String(data.chat_id || source.chat_id),
    user_id: String(source.user_id || source.chat_id),
    request_id:
      source.request_id ||
      String(source.chat_id) + '_' + String(source.update_id),
    slot_token: source.slot_token || null,

    profile,
    state,

    calendar_event_id: calendarEventId,
    calendar_url: derivation.calendar_url || null,
    appointment_start: appointmentStart,
    appointment_end: appointmentEnd,

   has_active_appointment: hasActiveAppointment,

    crm_status: 'NO_ESCRITO_ENSAYO'
  }
}];

const source =
  $('Preparar cita activa 05').first().json;

const zone = 'America/Lima';
const now = DateTime.now().setZone(zone);
const minimumStart = now.plus({ hours: 2 });

const results = [];

for (let dayOffset = 0; dayOffset <= 7; dayOffset++) {
  const day = now
    .startOf('day')
    .plus({ days: dayOffset });

  // Luxon: lunes = 1, domingo = 7.
  // Los lunes requieren coordinación especial.
  if (day.weekday === 1) {
    continue;
  }

  for (let hour = 10; hour <= 18; hour++) {
    const start = day.set({
      hour,
      minute: 0,
      second: 0,
      millisecond: 0
    });

    if (start <= minimumStart) {
      continue;
    }

    const end = start.plus({ minutes: 45 });
    const availabilityEnd = start.plus({ minutes: 60 });

    results.push({
      json: {
        chat_id: source.chat_id,
        request_id: source.request_id,
        profile: source.profile,

        calendar_event_id: source.calendar_event_id,
        old_appointment_start: source.appointment_start,
        old_appointment_end: source.appointment_end,

        slot_start: start.toISO(),
        slot_end: end.toISO(),
        availability_end: availabilityEnd.toISO(),

        slot_label: start
          .setLocale('es')
          .toFormat('ccc dd/LL · HH:mm'),

        slot_token: String(
          Math.floor(start.toSeconds())
        )
      }
    });

    if (results.length >= 24) {
      return results;
    }
  }
}

if (!results.length) {
  throw new Error(
    'No se generaron horarios para reprogramación'
  );
}

return results;

const checks = $input.all().map(item => item.json);

const candidates =
  $('Generar horarios reprogramacion 05')
    .all()
    .map(item => item.json);

const available = candidates.filter(
  (slot, index) => checks[index]?.available === true
);

if (!available.length) {
  throw new Error(
    'No existen horarios disponibles para reprogramar'
  );
}

// Máximo dos horarios por día y seis opciones en total.
const selected = [];
const perDay = {};

for (const slot of available) {
  const dayKey = String(slot.slot_start).slice(0, 10);

  perDay[dayKey] = perDay[dayKey] || 0;

  if (perDay[dayKey] >= 2) {
    continue;
  }

  selected.push(slot);
  perDay[dayKey]++;

  if (selected.length >= 6) {
    break;
  }
}

const keyboard = [];

for (let index = 0; index < selected.length; index += 2) {
  keyboard.push(
    selected.slice(index, index + 2).map(slot => ({
      text: slot.slot_label,
      callback_data:
        'orok:reslot:' + slot.slot_token
    }))
  );
}

const first = selected[0];

return [{
  json: {
    chat_id: first.chat_id,
    request_id: first.request_id,
    calendar_event_id: first.calendar_event_id,
    profile: first.profile,

    text:
      '¡Claro! 😊 Elige el nuevo horario que prefieras. ' +
      'Tu cita actual solo se modificará después de que ' +
      'selecciones una de estas opciones.',

    reply_markup: {
      inline_keyboard: keyboard
    },

    available_slots: selected
  }
}];

const appointment =
  $('Preparar cita activa 05').first().json;

const selection =
  $('Identificar evento ENSAYO1').first().json;

const zone = 'America/Lima';
const token = Number(selection.slot_token);

if (
  !Number.isInteger(token) ||
  token <= 0
) {
  throw new Error(
    'El botón no contiene un horario válido'
  );
}

const start = DateTime
  .fromSeconds(token, { zone });

const end = start.plus({ minutes: 45 });
const availabilityEnd =
  start.plus({ minutes: 60 });

const now = DateTime.now().setZone(zone);

const slotValid =
  start.isValid &&
  start > now.plus({ hours: 2 }) &&
  start < now.plus({ days: 8 });

return [{
  json: {
    chat_id: appointment.chat_id,
    user_id: appointment.user_id,
    request_id: appointment.request_id,

    query_id: selection.query_id,
    message_id: selection.message_id,

    calendar_event_id:
      appointment.calendar_event_id,

    old_appointment_start:
      appointment.appointment_start,

    old_appointment_end:
      appointment.appointment_end,

    profile: appointment.profile,

    slot_token: String(selection.slot_token),

    slot_start: start.toISO(),
    slot_end: end.toISO(),
    availability_end:
      availabilityEnd.toISO(),

    slot_label: start
      .setLocale('es')
      .toFormat("cccc dd/LL/yyyy, hh:mm a"),

    slot_valid: slotValid,

    crm_status: 'NO_ESCRITO_ENSAYO'
  }
}];

