CREATE OR REPLACE FUNCTION
public.orok_lola_ensayo05_reschedule(p jsonb)
RETURNS jsonb
LANGUAGE plpgsql
AS $function$
DECLARE
  s jsonb;
  d jsonb;
  ts timestamptz := clock_timestamp();

  vchat text := p->>'chat_id';
  source_event text := p->>'source_event_id';
  calendar_id text := p->>'calendar_event_id';

  inserted integer;
BEGIN
  IF vchat IS NULL OR vchat !~ '^[0-9]+$' THEN
    RAISE EXCEPTION 'Chat de ensayo inválido';
  END IF;

  IF source_event IS NULL OR source_event = '' THEN
    RAISE EXCEPTION 'Falta identificador de reprogramación';
  END IF;

  IF calendar_id IS NULL OR calendar_id = '' THEN
    RAISE EXCEPTION 'Falta identificador de Calendar';
  END IF;

  SELECT state
  INTO s
  FROM public.orok_lola_ensayo03_leads
  WHERE chat_id = vchat
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No existe la ficha de ensayo';
  END IF;

  INSERT INTO public.orok_lola_ensayo03_events(
    event_id,
    chat_id,
    kind,
    payload
  )
  VALUES(
    'rescheduled:' || source_event,
    vchat,
    'appointment_rescheduled',
    p
  )
  ON CONFLICT(event_id) DO NOTHING;

  GET DIAGNOSTICS inserted = ROW_COUNT;

  IF inserted = 0 THEN
    RETURN jsonb_build_object(
      'chat_id', vchat,
      'state', s,
      'duplicate', true,
      'accepted', false,
      'crm_status', 'NO_ESCRITO_ENSAYO'
    );
  END IF;

  d :=
    COALESCE(s->'derivation', '{}'::jsonb)
    ||
    jsonb_build_object(
      'status', 'appointment_confirmed',
      'calendar_event_id', calendar_id,
      'calendar_url', p->>'calendar_url',
      'appointment_start', p->>'appointment_start',
      'appointment_end', p->>'appointment_end',
      'reprogrammed_at', ts
    );

  s :=
    s
    ||
    jsonb_build_object(
      'stage', 'Cita agendada',
      'bot_paused', false,
      'derivation', d
    );

  s := jsonb_set(
    s,
    '{tasks}',
    COALESCE(s->'tasks', '[]'::jsonb)
    ||
    jsonb_build_array(
      jsonb_build_object(
        'role', 'vendedor',
        'action', 'appointment_rescheduled',
        'status', 'confirmada_ensayo',
        'assigned_to', 'Antonio Garces',
        'calendar_event_id', calendar_id,
        'starts_at', p->>'appointment_start',
        'previous_start', p->>'previous_start',
        'created_at', ts,
        'request_id', source_event
      )
    )
  );

  s := jsonb_set(
    s,
    '{notes}',
    COALESCE(s->'notes', '[]'::jsonb)
    ||
    jsonb_build_array(
      jsonb_build_object(
        'at', ts,
        'text',
        'Cita reprogramada en Google Calendar para '
        || COALESCE(p->>'slot_label', 'el nuevo horario')
        || '. Invitación actualizada para '
        || COALESCE(p->>'email', 'el cliente')
      )
    )
  );

  UPDATE public.orok_lola_ensayo03_leads
  SET
    state = s,
    updated_at = ts
  WHERE chat_id = vchat;

  RETURN jsonb_build_object(
    'chat_id', vchat,
    'state', s,
    'accepted', true,
    'should_send', true,
    'crm_status', 'NO_ESCRITO_ENSAYO'
  );
END;
$function$;

